def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Parse grid values into a dictionary for quick access
    grid = defaultdict(int)
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[(x - 1, y - 1)] = value

    # Initialize a 4D DP table
    dp = [[[[float('-inf')] * N for _ in range(N)] for _ in range(N)] for _ in range(N)]
    dp[0][0][0][0] = grid[(0, 0)]

    # Fill the DP table
    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(N):
                for j2 in range(N):
                    if (i1, j1) == (0, 0) and (i2, j2) == (0, 0):
                        continue
                    if i1 >= 1 and i2 >= 1:
                        dp[i1][j1][i2][j2] = max(dp[i1][j1][i2][j2], dp[i1-1][j1][i2-1][j2])
                    if i1 >= 1 and j2 >= 1:
                        dp[i1][j1][i2][j2] = max(dp[i1][j1][i2][j2], dp[i1-1][j1][i2][j2-1])
                    if j1 >= 1 and i2 >= 1:
                        dp[i1][j1][i2][j2] = max(dp[i1][j1][i2][j2], dp[i1][j1-1][i2-1][j2])
                    if j1 >= 1 and j2 >= 1:
                        dp[i1][j1][i2][j2] = max(dp[i1][j1][i2][j2], dp[i1][j1-1][i2][j2-1])

                    if dp[i1][j1][i2][j2] != float('-inf'):
                        if i1 == i2 and j1 == j2:
                            dp[i1][j1][i2][j2] += grid[(i1, j1)]
                        else:
                            dp[i1][j1][i2][j2] += grid[(i1, j1)] + grid[(i2, j2)]

    return max(0, dp[N-1][N-1][N-1][N-1])

def find_number_combinations():
