def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a transformation map from the rules
    transform_map = defaultdict(set)
    for x, y in rules:
        transform_map[x].add(y)

    # Convert the number to a string for easy manipulation
    original_number = str(n)
    queue = deque([original_number])
    visited = set([original_number])

    while queue:
        current_number = queue.popleft()

        # Try transforming each digit
        for i in range(len(current_number)):
            digit = int(current_number[i])
            if digit in transform_map:
                for new_digit in transform_map[digit]:
                    new_number = current_number[:i] + str(new_digit) + current_number[i+1:]
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    try:
        for participant, participant_statements in statements.items():
            for statement in participant_statements:
                # Ignore statements about the day of the week
                if any(day in statement for day in days_of_week):
                    continue

                # Determine if the statement is about guilt
                if "guilty" in statement:
                    # Check if the statement is about the scenario participant
                    if scenario in statement:
                        # If the participant is a liar, they can say they are not guilty
                        if participant in liar_count:
                            if "not guilty" in statement:
                                continue
                            else:
                                return False
                        # If the participant is not a liar, they must say they are guilty
                        else:
                            if "not guilty" in statement:
                                return False
                            else:
                                continue
                    else:
                        # If the statement is about another participant
                        target = statement.split()[0]
                        if participant in liar_count:
                            # Liars can say anyone is not guilty
                            if "not guilty" in statement:
                                continue
                            else:
                                # Liars can also say someone else is guilty, but it doesn't affect the scenario
                                continue
                        else:
                            # Truth-tellers must be consistent
                            if "not guilty" in statement and target == scenario:
                                return False
                            elif "guilty" in statement and target == scenario:
                                continue
        return True
    except Exception as e:
        return False

def calculate_score(system: int, points: str) -> list:
    if system not in (11, 21):
        raise ValueError("System must be either 11 or 21 points.")
    if not all(char in ('W', 'L') for char in points):
        raise ValueError("Points string must only contain 'W' and 'L' characters.")

    player_score = 0
    opponent_score = 0
    scores = []

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("The input must be a non-negative integer.")

    # Base case
    if n == 0:
        return 1

    # Create a list to store the catalan numbers up to n
    catalan = [0] * (n + 1)
    catalan[0] = 1

    # Fill the catalan array using the recursive formula
    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]

